INSERT INTO series ("name",photo,rating,status,review) VALUES
	 ('Дом Дракона','https://avatars.mds.yandex.net/get-kinopoisk-image/10592371/e81636b8-fb18-44fb-9074-11fffe9cfc4a/300x450',8,'watching'::public."seriesstatus",'Кто из Таргариенов займёт Железный трон? Грандиозная предыстория «Игры престолов»'),
	 ('Истинное Образование','https://avatars.mds.yandex.net/get-kinopoisk-image/10853012/1739525d-52e4-49fe-8d73-6d3f49532fd6/300x450',8,'watching'::public."seriesstatus",'Чтобы навести порядок в учебных заведениях, министр создаёт Бюро оперативного надзора за образованием. Наделённые практически безграничными полномочиями инспекторы защищают жертв в системе образования от агрессоров, кем бы те ни являлись — преподавателями, учениками или их родителями.'),
	 ('Извне','https://tinyurl.com/mu29w8ae',6,'watching'::public."seriesstatus",'Затерянный в лесу городок пленяет каждого, кому не посчастливилось туда попасть — покинуть это место невозможно. Днем невольные жители пытаются выстроить подобие нормального быта и найти способ выбраться, а по ночам спасаются от страшных лесных обитателей, которые приходят навестить горожан сразу после захода солнца.'),
	 ('Черные паруса','https://avatars.mds.yandex.net/get-kinopoisk-image/1629390/8d80273e-30df-4a07-95c9-8c7c75a49f72/300x450',9,'watched'::public."seriesstatus",'У клада на Острове сокровищ есть своя предыстория. Пиратская сага о капитане Флинте и молодом Джоне Сильвере'),
	 ('Паук-Нуар','https://avatars.mds.yandex.net/get-kinopoisk-image/10893610/3fba8635-74c6-49ba-84f3-761af8d4ae25/300x450',7,'watched'::public."seriesstatus",'Нью-Йорк, 1930-е. Частный детектив Бен Райлли, который переживает не лучшие времена, сталкивается со своим прошлым. Бену, единственному супергерою в городе, приходится бороться с внутренними демонами и снова стать Человеком-пауком, чтобы спасти мегаполис и себя.');
